package no.nav.syfo.frontier

import no.nav.syfo.util.dagerMellomDatoer
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.time.LocalDate

class DagerMellomDatoerTest {
    private val day = LocalDate.of(2024, 3, 1)

    @Test
    fun `same day is one day`() {
        assertEquals(1, dagerMellomDatoer(day, day))
    }

    @Test
    fun `counts both ends`() {
        assertEquals(10, dagerMellomDatoer(day, day.plusDays(9)))
    }

}

package no.nav.syfo.frontier

import no.nav.syfo.util.isBeforeOrEqual
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.time.LocalDate

class IsBeforeOrEqualTest {
    private val day = LocalDate.of(2024, 3, 1)

    @Test
    fun `a day is before or equal to itself`() {
        assertTrue(day.isBeforeOrEqual(day))
    }

    @Test
    fun `before and after`() {
        assertTrue(day.isBeforeOrEqual(day.plusDays(1)))
        assertFalse(day.plusDays(1).isBeforeOrEqual(day))
    }

}

package no.nav.syfo.frontier

import no.nav.syfo.util.isAfterOrEqual
import no.nav.syfo.util.isBeforeOrEqual
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.time.LocalDate

class LocalDateComparisonTest {
    private val day = LocalDate.of(2024, 3, 1)

    @Test
    fun `a day is before or equal to itself`() {
        assertTrue(day.isBeforeOrEqual(day))
    }

    @Test
    fun `before and after`() {
        assertTrue(day.isBeforeOrEqual(day.plusDays(1)))
        assertFalse(day.plusDays(1).isBeforeOrEqual(day))
    }

    @Test
    fun `a day is after or equal to itself`() {
        assertTrue(day.isAfterOrEqual(day))
    }

    @Test
    fun `after and before`() {
        assertTrue(day.plusDays(1).isAfterOrEqual(day))
        assertFalse(day.isAfterOrEqual(day.plusDays(1)))
    }

}

