package no.nav.syfo.frontier

import no.nav.syfo.domain.hasGjentakendeSykefravar
import testhelper.generator.generateOppfolgingstilfelle
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.time.LocalDate

class GjentakendeSykefravarTest {
    private val day = LocalDate.of(2024, 3, 1)

    private fun ago(days: Long) = LocalDate.now().minusDays(days)

    @Test
    fun `five tilfeller adding up to 100 days is gjentakende`() {
        val tilfeller = listOf(
            generateOppfolgingstilfelle(ago(500), ago(482)),
            generateOppfolgingstilfelle(ago(450), ago(431)),
            generateOppfolgingstilfelle(ago(400), ago(381)),
            generateOppfolgingstilfelle(ago(350), ago(331)),
            generateOppfolgingstilfelle(ago(300), ago(280)),
        )
        assertTrue(tilfeller.hasGjentakendeSykefravar())
    }

}
